361	  // 历史记录的某个展示字段若被存成 JSON 对象或数组，该单元格统一显示
362	  // “字段格式异常”，不展开其内部内容；异常只影响所在单元格，绝不能抛出
363	  // 异常拖垮整行乃至整份列表。null、字符串、数字、布尔值及缺失字段都不算
364	  // 异常，仍走各列原有的展示与兜底。
365	  var BAD_FIELD_TEXT = '字段格式异常';
366	  function isAbnormalField(value) {
367	    return value !== null && typeof value === 'object';
368	  }
369	  function markBadCell(td) {
370	    td.textContent = BAD_FIELD_TEXT;
371	  }
