380	  // 七列的展示定义，顺序即表格列顺序（表头也由同一份定义生成）。每列只
381	  // 描述“正常值如何显示”（含各列原有的兜底行为）；对象/数组的异常判定
382	  // 与替换由 buildRoomRow 统一处理，不在各列重复维护。个别列可用
383	  // renderBad 保留原有容器（如状态列的徽标），缺省时整格替换为异常文案。
384	  var ROOM_COLUMNS = [
385	    {
386	      key: 'id',
387	      label: '房间编号',
388	      className: 'id',
389	      render: function (td, value) { td.textContent = value || ''; }
390	    },
391	    {
392	      key: 'name',
393	      label: '名称',
394	      render: function (td, value) { td.textContent = value || ''; }
395	    },
396	    {
397	      key: 'game',
398	      label: '规则',
399	      render: function (td, value) {
400	        td.textContent = GAME_LABELS[value] || value || '';
401	      }
402	    },
403	    {
404	      key: 'capacity',
405	      label: '人数上限',
406	      render: function (td, value) {
407	        td.textContent = (value != null ? value : '') + ' 人';
408	      }
409	    },
410	    {
411	      key: 'turnSeconds',
412	      label: '时间限制',
413	      render: function (td, value) {
414	        td.textContent = value === 0 ? '不限时' : value + ' 秒';
415	      }
416	    },
417	    {
418	      key: 'status',
419	      label: '状态',
420	      render: function (td, value) {
421	        appendBadge(td, STATUS_LABELS[value] || value || '');
422	      },
423	      // 异常状态仍在原有徽标中显示提示文案。
424	      renderBad: function (td) { appendBadge(td, BAD_FIELD_TEXT); }
425	    },
426	    {
427	      key: 'createdAt',
428	      label: '创建时间',
429	      render: renderTimeCell
