435	  // 逐列渲染一个房间行：任何字段异常都只替换该单元格，其余字段照常显示。
436	  function buildRoomRow(r) {
437	    var tr = document.createElement('tr');
438	    ROOM_COLUMNS.forEach(function (col) {
439	      var td = document.createElement('td');
440	      if (col.className) td.className = col.className;
441	      var value = r[col.key];
442	      if (isAbnormalField(value)) {
443	        if (col.renderBad) col.renderBad(td);
444	        else markBadCell(td);
445	      } else {
446	        col.render(td, value);
447	      }
448	      tr.appendChild(td);
449	    });
450	    return tr;
451	  }
