95	// create 校验配置、写入新记录并返回保存后的房间。
96	func (s *roomStore) create(cfg roomConfig) (room, int, error) {
97		if code, msg, ok := validateConfig(cfg); !ok {
98			return room{}, code, errors.New(msg)
99		}
100	
101		s.mu.Lock()
102		defer s.mu.Unlock()
103	
104		records, used, err := s.load()
105		if err != nil {
106			return room{}, http.StatusInternalServerError, err
107		}
108	
109		now := time.Now()
110		newRoom := room{
111			ID:          uniqueRoomID(used),
112			Name:        strings.TrimSpace(cfg.Name),
113			Game:        cfg.Game,
114			Capacity:    cfg.Capacity,
115			TurnSeconds: cfg.TurnSeconds,
116			Status:      "waiting",
117			Visibility:  "public",
118			CreatedAt:   now.UTC().Format(time.RFC3339),
119		}
120	
121		encoded, err := json.Marshal(newRoom)
122		if err != nil {
123			return room{}, http.StatusInternalServerError, fmt.Errorf("序列化房间记录失败: %w", err)
124		}
125		records = append(records, encoded)
126		if err := s.writeAtomic(records); err != nil {
127			return room{}, http.StatusInternalServerError, err
128		}
129		return newRoom, http.StatusCreated, nil
130	}
131	
132	// writeAtomic 先写临时文件再重命名，避免保存失败时破坏原有数据。
133	func (s *roomStore) writeAtomic(records []json.RawMessage) error {
134		payload, err := json.MarshalIndent(records, "", "  ")
135		if err != nil {
136			return fmt.Errorf("序列化房间数据失败: %w", err)
137		}
138		payload = append(payload, '\n')
139	
140		dir := filepath.Dir(s.path)
141		tmp, err := os.CreateTemp(dir, ".rooms-*.tmp")
142		if err != nil {
143			return fmt.Errorf("创建临时数据文件失败: %w", err)
144		}
145		tmpName := tmp.Name()
146		cleanup := func() { _ = os.Remove(tmpName) }
147	
148		if _, err := tmp.Write(payload); err != nil {
149			_ = tmp.Close()
150			cleanup()
151			return fmt.Errorf("写入房间数据失败: %w", err)
152		}
153		if err := tmp.Sync(); err != nil {
154			_ = tmp.Close()
155			cleanup()
156			return fmt.Errorf("同步房间数据失败: %w", err)
157		}
158		if err := tmp.Close(); err != nil {
159			cleanup()
160			return fmt.Errorf("关闭临时数据文件失败: %w", err)
161		}
162		if err := os.Rename(tmpName, s.path); err != nil {
163			cleanup()
164			return fmt.Errorf("保存房间数据失败: %w", err)
165		}
166		return nil
167	}
