169	func uniqueRoomID(used map[string]bool) string {
170		var b [16]byte
171		for {
172			if _, err := rand.Read(b[:]); err != nil {
173				panic(fmt.Errorf("生成房间编号失败: %w", err))
174			}
175			id := hex.EncodeToString(b[:])
176			if !used[id] {
