225	func run() error {
226		if len(os.Args) < 2 {
227			printHelp()
228			return errors.New("expected serve or --help")
229		}
230		if os.Args[1] == "--help" || os.Args[1] == "-h" {
231			printHelp()
232			return nil
233		}
234		if os.Args[1] != "serve" {
235			return errors.New("expected serve or --help")
236		}
237		args := flag.NewFlagSet("score-arena serve", flag.ContinueOnError)
238		args.SetOutput(os.Stdout)
239		host := args.String("host", "127.0.0.1", "address to bind")
240		port := args.Int("port", 8080, "port to bind; 0 selects an available port")
241		data := args.String("data-dir", "data", "directory for local records")
242		if err := args.Parse(os.Args[2:]); errors.Is(err, flag.ErrHelp) {
243			return nil
244		} else if err != nil {
245			return err
246		}
247		if args.NArg() != 0 {
248			return errors.New("unexpected positional argument")
249		}
250		if *port < 0 || *port > 65535 {
251			return errors.New("port must be between 0 and 65535")
252		}
253		if err := os.MkdirAll(*data, 0700); err != nil {
254			return err
255		}
256		dataFile := filepath.Join(*data, "rooms.json")
257		store := newRoomStore(dataFile)
258	
259		// 首次启动时初始化空数组；已存在则原样保留。
260		file, err := os.OpenFile(dataFile, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
261		if err == nil {
262			_, writeErr := file.WriteString("[]\n")
263			closeErr := file.Close()
264			if writeErr != nil {
265				return writeErr
266			}
267			if closeErr != nil {
268				return closeErr
269			}
270		} else if !errors.Is(err, os.ErrExist) {
271			return err
272		}
273	
274		mux := http.NewServeMux()
275		mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
276			if r.URL.Path != "/" {
277				respond(w, http.StatusNotFound, map[string]string{"error": "not found"})
278				return
279			}
280			if r.Method != http.MethodGet {
281				methodNotAllowed(w, "GET")
282				return
283			}
284			w.Header().Set("Content-Type", "text/html; charset=utf-8")
285			_, _ = w.Write(indexPage)
286		})
287		mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
288			if r.Method != http.MethodGet {
289				methodNotAllowed(w, "GET")
290				return
291			}
292			respond(w, http.StatusOK, map[string]string{"status": "ok", "product": product})
293		})
294		mux.HandleFunc("/api/rooms", func(w http.ResponseWriter, r *http.Request) {
295			switch r.Method {
296			case http.MethodGet:
297				store.mu.Lock()
298				records, _, err := store.load()
299				store.mu.Unlock()
300				if err != nil {
301					respond(w, http.StatusInternalServerError, map[string]string{"error": "无法读取房间数据：" + err.Error()})
302					return
303				}
304				respond(w, http.StatusOK, map[string]any{resourceName: records})
305			case http.MethodPost:
306				handleCreateRoom(w, r, store)
307			default:
308				methodNotAllowed(w, "GET, POST")
309			}
310		})
311	
312		server := &http.Server{
313			Handler:           mux,
314			ReadHeaderTimeout: 5 * time.Second,
315		}
316		listener, err := net.Listen("tcp", net.JoinHostPort(*host, fmt.Sprint(*port)))
317		if err != nil {
318			return err
319		}
320		fmt.Printf("%s listening on http://%s\n", product, listener.Addr().String())
321		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
322		defer stop()
323		failures := make(chan error, 1)
324		go func() { failures <- server.Serve(listener) }()
325		select {
326		case err := <-failures:
327			if !errors.Is(err, http.ErrServerClosed) {
328				return err
329			}
330		case <-ctx.Done():
331			shutdown, cancel := context.WithTimeout(context.Background(), 3*time.Second)
332			defer cancel()
333			if err := server.Shutdown(shutdown); err != nil {
334				return err
335			}
336		}
337		return nil
338	}
339	
340	func handleCreateRoom(w http.ResponseWriter, r *http.Request, store *roomStore) {
341		// 限制请求体大小，避免异常大载荷。
342		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, 1<<20))
343		if err != nil {
344			respond(w, http.StatusBadRequest, map[string]string{"error": "读取请求体失败：" + err.Error()})
345			return
346		}
347	
348		cfg, ok := parseRoomFields(w, body)
349		if !ok {
350			return
351		}
352	
353		newRoom, status, err := store.create(cfg)
354		if err != nil {
355			respond(w, status, map[string]string{"error": err.Error()})
356			return
357		}
358		respond(w, http.StatusCreated, newRoom)
359	}
360	
361	func parseRoomFields(w http.ResponseWriter, body []byte) (roomConfig, bool) {
362		var fields map[string]json.RawMessage
363		if err := json.Unmarshal(body, &fields); err != nil || fields == nil {
364			respond(w, http.StatusBadRequest, map[string]string{"error": "请求体必须是单个 JSON 对象"})
365			return roomConfig{}, false
366		}
367	
368		var cfg roomConfig
369		missing := func(key string) (roomConfig, bool) {
370			respond(w, http.StatusBadRequest, map[string]string{"error": "缺少必填字段：" + key})
371			return roomConfig{}, false
372		}
373	
374		rawName, ok := fields["name"]
375		if !ok {
376			return missing("name")
377		}
378		if err := json.Unmarshal(rawName, &cfg.Name); err != nil {
379			respond(w, http.StatusBadRequest, map[string]string{"error": "name 必须是字符串"})
380			return roomConfig{}, false
381		}
382	
383		rawGame, ok := fields["game"]
384		if !ok {
385			return missing("game")
386		}
387		if err := json.Unmarshal(rawGame, &cfg.Game); err != nil {
388			respond(w, http.StatusBadRequest, map[string]string{"error": "game 必须是字符串"})
389			return roomConfig{}, false
390		}
391	
392		rawCapacity, ok := fields["capacity"]
393		if !ok {
394			return missing("capacity")
395		}
396		capacity, err := parseStrictInt(rawCapacity)
397		if err != nil {
398			respond(w, http.StatusBadRequest, map[string]string{"error": "capacity 必须是整数：" + err.Error()})
399			return roomConfig{}, false
400		}
401		cfg.Capacity = capacity
402	
403		rawTurn, ok := fields["turnSeconds"]
404		if !ok {
405			return missing("turnSeconds")
406		}
407		turn, err := parseStrictInt(rawTurn)
408		if err != nil {
409			respond(w, http.StatusBadRequest, map[string]string{"error": "turnSeconds 必须是整数：" + err.Error()})
410			return roomConfig{}, false
411		}
412		cfg.TurnSeconds = turn
413	
414		return cfg, true
415	}
416	
417	// parseStrictInt 只接受单个 JSON 整数（拒绝小数、科学计数法、字符串、布尔、null、对象、数组及尾随内容）。
418	func parseStrictInt(raw json.RawMessage) (int, error) {
419		dec := json.NewDecoder(strings.NewReader(string(raw)))
420		dec.UseNumber()
421		var v any
422		if err := dec.Decode(&v); err != nil {
423			return 0, errors.New("值不是数字")
424		}
425		var extra any
426		if err := dec.Decode(&extra); err != io.EOF {
427			return 0, errors.New("包含多余内容")
428		}
429		// 带引号的字符串会解成 Go string 而非 json.Number，断言失败即可拒绝。
430		n, ok := v.(json.Number)
431		if !ok {
432			return 0, errors.New("值不是数字")
433		}
434		i, err := n.Int64()
435		if err != nil {
436			return 0, errors.New("不是整数（不接受小数）")
437		}
438		return int(i), nil
439	}
440	
441	func printHelp() {
442		fmt.Println("ScoreArena - 桌面规则游戏与赛事管理")
443		fmt.Println("Usage: go run . serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]")
444		fmt.Println("       go run . --help")
445		fmt.Println("Defaults: --host 127.0.0.1 --port 8080 --data-dir data")
446	}
447	
448	func main() {
449		if err := run(); err != nil {
450			fmt.Fprintln(os.Stderr, err)
451			os.Exit(1)
452		}
453	}
