  name: '不应被猜出的房间',
  game: 'gomoku',
  capacity: 2,
  turnSeconds: 0,
  status: 'waiting',
  visibility: 'public',
  createdAt: '2026-04-01T00:00:00Z',
};
const LURE_TOKENS = ['lure-room-id', '不应被猜出的房间'];

